    def review_ocr(self, action: Literal["list", "accept", "correct"], document_id: str, *, threshold: Optional[float] = None, offset: Optional[int] = None, limit: Optional[int] = None, revision: Optional[int] = None, page: Optional[int] = None, index: Optional[int] = None, expected_text: Optional[str] = None, text: Optional[str] = None) -> Any:
        """Verify OCR text.

        List low/unknown-confidence OCR words with page coordinates and review
        state, or accept/correct one word. Requires documentId; mutations also
        require revision and expectedText from the list to reject stale edits.
        Save afterward to replace the invisible OCR text layer. Never paints
        over the scan. Results are paginated.

        Args:
            action (one of "list", "accept", "correct", required)
            document_id (string, required) [MCP: documentId]
            threshold (number; min 0, max 100)
            offset (integer; min 0)
            limit (integer; min 1, max 1000)
            revision (integer)
            page (integer; min 1)
            index (integer; min 0)
            expected_text (string) [MCP: expectedText]
            text (string)

        MCP tool ``app_review_ocr`` (modifies or discards state).
        """
        return self._call_tool("app_review_ocr", _pack({"action": action, "documentId": document_id, "threshold": threshold, "offset": offset, "limit": limit, "revision": revision, "page": page, "index": index, "expectedText": expected_text, "text": text}))

    def get_page_text(self, *, page: Optional[int] = None) -> Any:
        """Read existing page text.

        Read existing PDF page text without mouse automation. Returns
        document-bound span IDs, readable merged text, page-space bounding
        boxes, PDF anchors, font family/size, rotation and fill colour when
        recoverable. Pass a page number or omit it for the current page. Text is
        never sent outside the local MCP connection.

        Args:
            page (integer; min 1): 1-based page number; defaults to the current
                page.

        MCP tool ``app_get_page_text`` (read-only).
        """
        return self._call_tool("app_get_page_text", _pack({"page": page}))

    def replace_text(self, span_id: str, expected_text: str, new_text: str, *, color: Optional[str] = None) -> Any:
        """Replace existing page text.

        Replace one existing PDF text span returned by app_get_page_text.
        Requires the exact expected text to reject stale IDs. Preserves the page
        artwork by refusing edits that cannot remove the original text in place;
        fits the replacement inside its original width and embeds a full
        fallback font when the subset lacks glyphs. Changes stay pending until
        app_save_pdf is called. One line per call; for translation, map
        translated lines to span IDs and call repeatedly.

        Args:
            span_id (string, required) [MCP: spanId]: Opaque span ID from
                app_get_page_text.
            expected_text (string, required) [MCP: expectedText]: Exact current
                text returned for that span.
            new_text (string, required) [MCP: newText]: Replacement text on one
                line (may be empty to delete).
            color (string): Required only when the source fill colour could not
                be recovered.

        MCP tool ``app_replace_text`` (modifies or discards state).
        """
        return self._call_tool("app_replace_text", _pack({"color": color, "expectedText": expected_text, "newText": new_text, "spanId": span_id}))

    def translate_page(self, replacements: List[Dict[str, Any]], *, page: Optional[int] = None) -> Any:
        """Replace page text in bulk.

        Replace many text spans of one page in a single call, for example to
        translate the page. Takes spans from app_get_page_text with their exact
        expected text. All or nothing: if any replacement fails, nothing changes
        and the result lists the error per span. Same rules as app_replace_text
        (in-place removal, fit to the original width, full fallback font when
        the subset lacks glyphs), checked together on one copy of the PDF and
        applied as one undo step. Changes stay pending until app_save_pdf is
        called.

        Args:
            replacements (array, required): One entry per span to replace, each
                on one line.
            page (integer; min 1): 1-based page number; defaults to the page of
                the first spanId.

        MCP tool ``app_translate_page`` (modifies or discards state).
        """
        return self._call_tool("app_translate_page", _pack({"page": page, "replacements": replacements}))

    def set_measure_scale(self, pixels_per_unit: float, unit: str) -> Any:
        """Set measurement scale.

        Set the active document's measurement scale calibration (pixels per unit
        + unit, e.g. ~2.835 px/mm for 1:1 at 72 dpi) and recalculate every
        measurement annotation.

        Args:
            pixels_per_unit (number, required) [MCP: pixelsPerUnit]
            unit (string, required): Unit name, e.g. mm, cm, m, in, ft.

        MCP tool ``app_set_measure_scale`` (modifies or discards state).
        """
        return self._call_tool("app_set_measure_scale", _pack({"pixelsPerUnit": pixels_per_unit, "unit": unit}))

    def get_takeoff(self, *, name: Optional[str] = None, schedule_id: Optional[str] = None) -> Any:
        """Get quantity take-off.

        Return take-off totals for the user's named schedules (Staten): per
        schedule the element count, the numeric column grand totals (e.g. area
        m2, length m, count), and per-group subtotals. Optionally target one
        schedule by id or name; otherwise all schedules are returned.
        Image/thumbnail columns are reported as counts, never as data-URLs.

        Args:
            name (string): Target one schedule by its display name.
            schedule_id (string) [MCP: scheduleId]: Target one schedule by its
                id.

        MCP tool ``app_get_takeoff`` (read-only).
        """
        return self._call_tool("app_get_takeoff", _pack({"name": name, "scheduleId": schedule_id}))

    def place_schedule(self, *, config: Optional[Dict[str, Any]] = None, name: Optional[str] = None, page: Optional[float] = None, schedule_id: Optional[str] = None, template_id: Optional[str] = None, x: Optional[float] = None, y: Optional[float] = None) -> Any:
        """Place quantity schedule.

        Build a quantities schedule (Staat) from the annotations in the open
        document and place it on the page as a table annotation. Without
        scheduleId a new schedule is created from a template (default 'area');
        `config` then overrides its categories/fields/sort. The table contents
        are computed by the app from the live annotations - the caller supplies
        no cell values.

        Args:
            config (object): Schedule config: categories, fields, filters, sort,
                itemize, format. Overrides the template.
            name (string): Display name for the schedule.
            page (number): Page to place the table on (default: current page).
            schedule_id (string) [MCP: scheduleId]: Reuse an existing schedule
                instead of creating one.
            template_id (string) [MCP: templateId]: Template for a new schedule:
                area, length, count, symbol, text, image or full. Default: area.
            x (number): Left edge in page points (default 40).
            y (number): Top edge in page points (default 40).

        MCP tool ``app_place_schedule`` (changes state).
        """
        return self._call_tool("app_place_schedule", _pack({"config": config, "name": name, "page": page, "scheduleId": schedule_id, "templateId": template_id, "x": x, "y": y}))

    def structural_layout(self, origin: Dict[str, Any], bays_x: Any, bays_y: Any, *, beams: Optional[Any] = None, columns: Optional[Any] = None, dry_run: Optional[bool] = None, floors: Optional[Any] = None, grid_bubble_mm: Optional[float] = None, grid_extension_mm: Optional[float] = None, label_style_x: Optional[Literal["letters", "numbers"]] = None, label_style_y: Optional[Literal["letters", "numbers"]] = None, labels_y_from_bottom: Optional[bool] = None, level_markers: Optional[bool] = None, page: Optional[float] = None, scale: Optional[str] = None, schedule: Optional[Any] = None, set_measure_scale: Optional[bool] = None, tags: Optional[bool] = None, text_height_mm: Optional[float] = None) -> Any:
        """Set out structural layout.

        Set out a structural floor plan in one undoable step: the grid (lettered
        and numbered grid lines with bubbles), columns on the grid
        intersections, beams along the grid lines, a span-direction arrow per
        floor bay carrying the real span, spot elevations, position tags
        (position number / section / level) and - unless switched off - a
        quantity schedule grouped by IFC category. Bay sizes are REAL
        millimetres; the app converts them to page points at `scale` and also
        calibrates the measuring scale so later measurements agree. Profiles:
        "HE200B", "HEA 200", "IPE 300", "UNP 200", "K100/5" (square hollow
        section; rectangular: "Koker 100x50x5"), "L 100x100x10" (steel) or
        "300x500" (concrete b x h in mm). Use dryRun to see what would be placed
        without touching the drawing.

        Args:
            origin (object, required): First grid intersection, in page points
                (top-left origin, 100% zoom).
            bays_x (any, required) [MCP: baysX]: Bay sizes left to right in mm:
                [5400,5400], '2x5400' or '5400 6000'.
            bays_y (any, required) [MCP: baysY]: Bay sizes top to bottom in mm,
                same notations as baysX.
            beams (any): false to omit, or { profile, direction: x|y|both,
                prefix, levelMm, edgeOnly }.
            columns (any): false to omit, or { profile, prefix, levelMm, skip:
                [grid labels] }.
            dry_run (boolean) [MCP: dryRun]: Only compute and report; draw
                nothing.
            floors (any): false to omit, or { direction: x|y|shortest,
                thicknessMm, levelMm, prefix, text }.
            grid_bubble_mm (number) [MCP: gridBubbleMm]: Grid bubble radius in
                PAPER mm (default 4).
            grid_extension_mm (number) [MCP: gridExtensionMm]: How far a grid
                line runs past the outer bay, in mm (default 1500).
            label_style_x (one of "letters", "numbers") [MCP: labelStyleX]:
                Label style for the vertical grid lines (default letters).
            label_style_y (one of "letters", "numbers") [MCP: labelStyleY]:
                Label style for the horizontal grid lines (default numbers).
            labels_y_from_bottom (boolean) [MCP: labelsYFromBottom]: Number the
                horizontal grid lines from the bottom up, as on a drawing (default
                true).
            level_markers (boolean) [MCP: levelMarkers]: Place a spot elevation
                per floor bay when a level is given (default true).
            page (number): Page to draw on (default: current page).
            scale (string): Drawing scale, e.g. '1:100' (default) or '1:50'.
            schedule (any): false to omit, or { name, x, y, itemize } for the
                quantity schedule.
            set_measure_scale (boolean) [MCP: setMeasureScale]: Also calibrate
                the document's measuring scale to this drawing scale (default true).
            tags (boolean): Tag each element with position number, section and
                level (default true).
            text_height_mm (number) [MCP: textHeightMm]: Tag text height in
                PAPER mm (default 2.5).

        MCP tool ``app_structural_layout`` (changes state).
        """
        return self._call_tool("app_structural_layout", _pack({"baysX": bays_x, "baysY": bays_y, "beams": beams, "columns": columns, "dryRun": dry_run, "floors": floors, "gridBubbleMm": grid_bubble_mm, "gridExtensionMm": grid_extension_mm, "labelStyleX": label_style_x, "labelStyleY": label_style_y, "labelsYFromBottom": labels_y_from_bottom, "levelMarkers": level_markers, "origin": origin, "page": page, "scale": scale, "schedule": schedule, "setMeasureScale": set_measure_scale, "tags": tags, "textHeightMm": text_height_mm}))

    def list_commands(self, *, filter: Optional[str] = None) -> Any:
        """List app commands.

        List EVERY function the app exposes: each ribbon tab, each ribbon button
        on every tab (label, tab, disabled/active state) plus every drawing
        tool. Use this to discover how a feature is called before running it
        with app_run_command. Command ids: 'ribbon-tab:<tab>' (activate a ribbon
        tab), 'ribbon:#<id>' (stable), 'ribbon:<tab>:<n>' (button without an id,
        only stable within one version), 'tool:<name>'. Optional `filter`
        narrows by text (matches id, label, title or tab). Tabs and buttons that
        an extension adds carry the extension tab id in `tab`, including tabs an
        extension put into the ribbon itself. Extension actions appear as
        'ext:<extensionId>:<itemId>'.

        Args:
            filter (string): Case-insensitive text filter, e.g. 'scale',
                'snippet', 'export'.

        MCP tool ``app_list_commands`` (read-only).
        """
        return self._call_tool("app_list_commands", _pack({"filter": filter}))

    def run_command(self, command: str) -> Any:
        """Run app command.

        Run any command returned by app_list_commands: activates a ribbon tab
        ('ribbon-tab:<tab>'), clicks the ribbon button (switching to its tab
        first), runs an extension action ('ext:...') or activates the tool.
        Disabled buttons are refused.

        Args:
            command (string, required): Command id from app_list_commands, e.g.
                'ribbon:#btn-vector-snippet', 'ribbon-tab:view' or
                'tool:measureArea'.

        MCP tool ``app_run_command`` (modifies or discards state).
        """
        return self._call_tool("app_run_command", _pack({"command": command}))

    def read_ui(self, *, include_hidden: Optional[bool] = None, max_depth: Optional[int] = None, max_nodes: Optional[int] = None, max_text: Optional[int] = None, selector: Optional[str] = None) -> Any:
        """Read interface state.

        Read the LIVE app's interface as a compact accessibility-style tree, to
        check what a click did without a screenshot. Each node has a role
        (button, tab, tabpanel, group, combobox, option, checkbox, status, text,
        ...), a name and only the state that applies: disabled, checked,
        pressed, selected, expanded, active, focused, readonly, plus
        value/valueText for inputs. Ribbon tabs carry `tab` and the `command`
        'ribbon-tab:<tab>'; ribbon buttons and extension controls carry the
        `command` that app_run_command runs. Without `selector` it reads the
        ribbon (only the active tab's content exists), the side panels, the bars
        above the document, floating palettes, open dialogs and the status bar,
        each as a region. With `selector` it reads the matching elements
        instead, for example an extension's panel. Reads only: it never switches
        ribbon tabs. maxDepth, maxNodes and maxText keep the output small;
        `truncated` says when something was left out.

        Args:
            include_hidden (boolean; default false) [MCP: includeHidden]: Also
                list hidden elements, marked with state.hidden.
            max_depth (integer; default 12, min 1, max 40) [MCP: maxDepth]:
                Maximum depth of the tree.
            max_nodes (integer; default 400, min 1, max 3000) [MCP: maxNodes]:
                Maximum number of nodes over all regions together.
            max_text (integer; default 80, min 8, max 1000) [MCP: maxText]:
                Maximum length of a name, description or value.
            selector (string): CSS selector of the element(s) to read, e.g.
                '.ribbon-container', '#left-panel' or '.status-bar'. Default: the
                standard regions.

        MCP tool ``app_read_ui`` (read-only).
        """
        return self._call_tool("app_read_ui", _pack({"includeHidden": include_hidden, "maxDepth": max_depth, "maxNodes": max_nodes, "maxText": max_text, "selector": selector}))

    def snippet_cut(self, x: float, y: float, width: float, height: float, *, page: Optional[float] = None) -> Any:
        """Cut vector snippet.

        Cut a rectangular area from a page of the active document as a VECTOR
        snippet (not a raster screenshot) and put it on the app's snippet
        clipboard. Coordinates are app points (top-left origin, 100% zoom).
        Paste it into any open document with app_snippet_paste.

        Args:
            x (number, required): Left edge in app points.
            y (number, required): Top edge in app points.
            width (number, required): Width in app points.
            height (number, required): Height in app points.
            page (number): Page to cut from (default: current page).

        MCP tool ``app_snippet_cut`` (changes state).
        """
        return self._call_tool("app_snippet_cut", _pack({"height": height, "page": page, "width": width, "x": x, "y": y}))

    def snippet_paste(self, *, page: Optional[float] = None, x: Optional[float] = None, y: Optional[float] = None) -> Any:
        """Paste vector snippet.

        Paste the vector snippet from the snippet clipboard into the active
        document at real size, as a movable annotation. It stays vector in the
        saved PDF.

        Args:
            page (number): Target page (default: current page).
            x (number): Left edge in app points (default 40).
            y (number): Top edge in app points (default 40).

        MCP tool ``app_snippet_paste`` (changes state).
        """
        return self._call_tool("app_snippet_paste", _pack({"page": page, "x": x, "y": y}))

    def import_cad(self, path: str, *, area: Optional[Literal["extents", "limits"]] = None, colors: Optional[Literal["file", "black", "gray", "mono", "single"]] = None, fonts: Optional[List[Dict[str, Any]]] = None, hatch: Optional[Literal["all", "solid_only", "outline", "none"]] = None, images: Optional[bool] = None, include_off_layers: Optional[bool] = None, layers_as_ocg: Optional[bool] = None, layers_off: Optional[List[str]] = None, layers_on: Optional[List[str]] = None, lineweight: Optional[Literal["file", "fixed", "pens"]] = None, lineweight_mm: Optional[float] = None, margin_mm: Optional[float] = None, max_image_megapixels: Optional[float] = None, mono_threshold: Optional[float] = None, opacity: Optional[float] = None, orientation: Optional[Literal["auto", "portrait", "landscape"]] = None, paper: Optional[Literal["auto", "A4", "A3", "A3L", "A2", "A2L", "A1", "A1L", "A0", "Letter", "Tabloid", "custom"]] = None, paper_height_mm: Optional[float] = None, paper_width_mm: Optional[float] = None, pens: Optional[List[Dict[str, Any]]] = None, placement: Optional[Literal["center", "lower_left", "origin"]] = None, reuse_blocks: Optional[bool] = None, rotation: Optional[float] = None, scale: Optional[float] = None, search_paths: Optional[List[str]] = None, single_color: Optional[str] = None, space: Optional[str] = None, target: Optional[Literal["new", "append", "underlay"]] = None, text: Optional[bool] = None, units: Optional[Literal["file", "mm", "cm", "m", "in", "ft"]] = None, window: Optional[List[float]] = None, xrefs: Optional[bool] = None) -> Any:
        """Import CAD drawing.

        Import a DWG or DXF drawing as a vector PDF page, without opening the
        import dialog. Choose the space (model space or a layout), the scale,
        the paper size, the layers and what happens with the result: a new
        document, a new page after the current one, or an underlay on the
        current page. Settings that are left out take the value the import
        dialog remembered, otherwise its default. Returns the pages that were
        made, warnings about anything that could not be converted and the names
        of external files. Fails while the import dialog is open.

        Args:
            path (string, required): Absolute path of the .dwg or .dxf file.
            area (one of "extents", "limits"): What part of the model space is
                converted.
            colors (one of "file", "black", "gray", "mono", "single"): Colour
                mode.
            fonts (array): Font replacements: [{ "from": "name in the drawing",
                "family": "sans" or "mono", "bold": false, "italic": false }].
            hatch (one of "all", "solid_only", "outline", "none")
            images (boolean): Embed images.
            include_off_layers (boolean) [MCP: includeOffLayers]: Include
                switched-off layers as hidden PDF layers instead of leaving them
                out.
            layers_as_ocg (boolean) [MCP: layersAsOcg]: Keep the layers as PDF
                layers.
            layers_off (array) [MCP: layersOff]: Layer names to leave out, on
                top of the layers the file switches off.
            layers_on (array) [MCP: layersOn]: Layer names to include although
                the file switches them off.
            lineweight (one of "file", "fixed", "pens"): Line weights from the
                file, one fixed weight, or the colour table in pens.
            lineweight_mm (number) [MCP: lineweightMm]: Line weight in mm for
                lineweight fixed.
            margin_mm (number) [MCP: marginMm]: Margin around the drawing in mm,
                0 to 200.
            max_image_megapixels (number) [MCP: maxImageMegapixels]: Largest
                image that is embedded, in megapixels, 1 to 200.
            mono_threshold (number) [MCP: monoThreshold]: Brightness threshold
                in percent for colors mono, 0 to 100.
            opacity (number): Opacity of an underlay, 0.05 to 1 (default 0.5).
                Only with target underlay.
            orientation (one of "auto", "portrait", "landscape")
            paper (one of "auto", "A4", "A3", "A3L", "A2", "A2L", "A1", "A1L",
                "A0", "Letter", "Tabloid", "custom"): Paper size. A layout keeps its
                own paper unless this is given.
            paper_height_mm (number) [MCP: paperHeightMm]: Height in mm for
                paper custom.
            paper_width_mm (number) [MCP: paperWidthMm]: Width in mm for paper
                custom.
            pens (array): Colour table for lineweight pens: [{ "color":
                "#RRGGBB", "lineweightMm": 0.35 }].
            placement (one of "center", "lower_left", "origin")
            reuse_blocks (boolean) [MCP: reuseBlocks]: Store repeated blocks
                once in the PDF.
            rotation (number): Rotate the drawing before placing it, in degrees.
            scale (number): Denominator N of 1:N. 0 fits the drawing on the
                paper.
            search_paths (array) [MCP: searchPaths]: Extra folders to look in
                for external references and images.
            single_color (string) [MCP: singleColor]: Colour #RRGGBB for colors
                single.
            space (string): "model" or the name of a layout (default: what the
                file suggests).
            target (one of "new", "append", "underlay"): new = a new document
                (default), append = a new page after the current page, underlay = on
                the current page. append without an open document becomes new.
            text (boolean): Convert text.
            units (one of "file", "mm", "cm", "m", "in", "ft"): Drawing unit;
                file = the unit in the file.
            window (array): Convert only this window: [x0, y0, x1, y1] in
                drawing units. Excludes area.
            xrefs (boolean): Load external references.

        MCP tool ``app_import_cad`` (changes state).
        """
        return self._call_tool("app_import_cad", _pack({"area": area, "colors": colors, "fonts": fonts, "hatch": hatch, "images": images, "includeOffLayers": include_off_layers, "layersAsOcg": layers_as_ocg, "layersOff": layers_off, "layersOn": layers_on, "lineweight": lineweight, "lineweightMm": lineweight_mm, "marginMm": margin_mm, "maxImageMegapixels": max_image_megapixels, "monoThreshold": mono_threshold, "opacity": opacity, "orientation": orientation, "paper": paper, "paperHeightMm": paper_height_mm, "paperWidthMm": paper_width_mm, "path": path, "pens": pens, "placement": placement, "reuseBlocks": reuse_blocks, "rotation": rotation, "scale": scale, "searchPaths": search_paths, "singleColor": single_color, "space": space, "target": target, "text": text, "units": units, "window": window, "xrefs": xrefs}))

    def export_cad(self, path: str, *, allow_large: Optional[bool] = None, annotations: Optional[bool] = None, area: Optional[List[float]] = None, format: Optional[Literal["dxf", "dxf_binary", "dwg"]] = None, layers: Optional[Literal["ocg_then_style", "style", "single"]] = None, layers_off: Optional[List[str]] = None, origin: Optional[Literal["page", "area", "model"]] = None, pages: Optional[str] = None, scale: Optional[float] = None, scale_mode: Optional[Literal["paper", "measure", "custom"]] = None, units: Optional[Literal["mm", "cm", "m", "in"]] = None) -> Any:
        """Export to CAD drawing.

        Export pages of the current document to DXF or DWG, without opening the
        export dialog. Reads the file on disk (save first); one page writes to
        `path`, several pages get `_p<page>` behind the name. Settings that are
        left out take the value the export dialog remembered, otherwise its
        default. Returns the files that were written with their object counts,
        warnings and, on a failure, a code (tooLarge, noModelSpace,
        modelSpaceAmbiguous, modelUnitsUnknown, failed). Fails while the export
        dialog is open.

        Args:
            path (string, required): Absolute path of the target file (.dxf or
                .dwg). Gives the format when format is left out.
            allow_large (boolean) [MCP: allowLarge]: Export a page with more
                objects than the limit anyway (default false: such a page fails with
                code tooLarge).
            annotations (boolean): Include the annotations on layers OPS_<type>.
            area (array): Export only this window: [x0, y0, x1, y1] in page
                points with the origin at the top left, as annotations are
                positioned.
            format (one of "dxf", "dxf_binary", "dwg"): Output format; sets the
                extension of path.
            layers (one of "ocg_then_style", "style", "single"): PDF layers then
                line style, line style only, or one layer.
            layers_off (array) [MCP: layersOff]: Layer names (as the export
                makes them) to leave out.
            origin (one of "page", "area", "model"): Where (0,0) of the drawing
                is: the lower left of the page (default), of the area, or the
                original model coordinates of an imported page.
            pages (string): "current" (default), "all" or a range like "1-3,5".
            scale (number): Denominator N of 1:N for scaleMode custom (implies
                it).
            scale_mode (one of "paper", "measure", "custom") [MCP: scaleMode]:
                paper = paper size, measure = the measure scale of the app at the
                area or page (default), custom = 1:scale.
            units (one of "mm", "cm", "m", "in"): Drawing unit of the output.

        MCP tool ``app_export_cad`` (modifies or discards state).
        """
        return self._call_tool("app_export_cad", _pack({"allowLarge": allow_large, "annotations": annotations, "area": area, "format": format, "layers": layers, "layersOff": layers_off, "origin": origin, "pages": pages, "path": path, "scale": scale, "scaleMode": scale_mode, "units": units}))

    def print_to_pdf(self, path: str, *, auto_rotate: Optional[bool] = None, center: Optional[bool] = None, content: Optional[Literal["document", "document-and-markups"]] = None, orientation: Optional[Literal["auto", "portrait", "landscape"]] = None, pages: Optional[str] = None, paper: Optional[Literal["page", "A0", "A1", "A2", "A3", "A4", "A5", "A0L", "A1L", "A2L", "A3L", "Letter", "Legal", "Tabloid"]] = None, scaling: Optional[Literal["fit", "shrink", "actual", "custom-scale"]] = None, zoom: Optional[float] = None) -> Any:
        """Print to PDF file.

        Print the current document to a PDF file, without opening the print
        dialog. Takes the route of the "Save as PDF" target in that dialog: no
        printer and no driver, the app writes the print PDF itself, so text
        stays text and the sheet lies in the file exactly as chosen. Settings
        that are left out take the value the print dialog remembered, otherwise
        its default; `pages` always starts at all pages. Returns the sheet size
        and orientation per page, the scale that was used and warnings about
        pages that do not fit. Fails while the print dialog is open.

        Args:
            path (string, required): Absolute path of the PDF file to write
                (.pdf). A file that is open in the app is refused.
            auto_rotate (boolean) [MCP: autoRotate]: true means orientation
                "auto"; false takes the orientation from Page Setup, otherwise
                portrait. May not contradict orientation.
            center (boolean): Centre the page on the sheet.
            content (one of "document", "document-and-markups"): "document"
                leaves the annotation layer out; watermarks and text edits stay,
                they are document content.
            orientation (one of "auto", "portrait", "landscape"): Orientation of
                the sheet; "auto" follows the page, as Auto-rotate in the dialog
                does. Left out: what the next print would already get.
            pages (string): "all" (default), "current" or a range like "1-3,5".
            paper (one of "page", "A0", "A1", "A2", "A3", "A4", "A5", "A0L",
                "A1L", "A2L", "A3L", "Letter", "Legal", "Tabloid"): Sheet size.
                "page" = every page on a sheet of its own size. Left out: the paper
                the Page Setup of this document asks for, otherwise "page".
            scaling (one of "fit", "shrink", "actual", "custom-scale"): fit =
                fit on the sheet, shrink = only shrink when the page does not fit,
                actual = real size, custom-scale = the percentage in zoom.
            zoom (number): Page zoom in percent, 10 to 400. Implies scaling
                "custom-scale".

        MCP tool ``app_print_to_pdf`` (modifies or discards state).
        """
        return self._call_tool("app_print_to_pdf", _pack({"autoRotate": auto_rotate, "center": center, "content": content, "orientation": orientation, "pages": pages, "paper": paper, "path": path, "scaling": scaling, "zoom": zoom}))

    def print(self, printer: str, *, auto_rotate: Optional[bool] = None, center: Optional[bool] = None, content: Optional[Literal["document", "document-and-markups"]] = None, copies: Optional[float] = None, orientation: Optional[Literal["auto", "portrait", "landscape"]] = None, pages: Optional[str] = None, paper: Optional[Literal["printer", "A0", "A1", "A2", "A3", "A4", "A5", "A0L", "A1L", "A2L", "A3L", "Letter", "Legal", "Tabloid"]] = None, scaling: Optional[Literal["fit", "shrink", "actual", "custom-scale"]] = None, zoom: Optional[float] = None) -> Any:
        """Print to printer.

        Print the current document to a printer, without opening the print
        dialog. Same page selection, paper, scale, position and content as that
        dialog, and the same background job. Settings that are left out take the
        value the print dialog remembered, otherwise its default; `pages` always
        starts at all pages. Returns the printer, the sheet with its
        orientation, the scale that was used, the number of copies and warnings
        about pages that do not fit. Paper really comes out of the printer, so
        ask the user before calling this. Fails on an unknown printer and while
        the print dialog is open.

        Args:
            printer (string, required): Name of the print queue, exactly as
                app_list_printers reports it.
            auto_rotate (boolean) [MCP: autoRotate]: true means orientation
                "auto"; false takes the orientation from Page Setup, otherwise
                portrait. May not contradict orientation.
            center (boolean): Centre the page on the sheet.
            content (one of "document", "document-and-markups"): "document"
                leaves the annotation layer out; watermarks and text edits stay,
                they are document content.
            copies (number): Number of copies, 1 to 999 (default: what the print
                dialog remembered).
            orientation (one of "auto", "portrait", "landscape"): Orientation of
                the sheet; "auto" follows the page, as Auto-rotate in the dialog
                does. Left out: what the next print would already get.
            pages (string): "all" (default), "current" or a range like "1-3,5".
            paper (one of "printer", "A0", "A1", "A2", "A3", "A4", "A5", "A0L",
                "A1L", "A2L", "A3L", "Letter", "Legal", "Tabloid"): Sheet size.
                "printer" = the paper that is in the printer. Left out: the paper
                the Page Setup of this document asks for, otherwise "printer".
            scaling (one of "fit", "shrink", "actual", "custom-scale"): fit =
                fit on the sheet, shrink = only shrink when the page does not fit,
                actual = real size, custom-scale = the percentage in zoom.
            zoom (number): Page zoom in percent, 10 to 400. Implies scaling
                "custom-scale".

        MCP tool ``app_print`` (modifies or discards state).
        """
        return self._call_tool("app_print", _pack({"autoRotate": auto_rotate, "center": center, "content": content, "copies": copies, "orientation": orientation, "pages": pages, "paper": paper, "printer": printer, "scaling": scaling, "zoom": zoom}))

    def list_printers(self) -> Any:
        """List printers.

        List the printers the app knows, with the system default printer and,
        per printer, the driver, the port and whether it writes to a file
        instead of to paper. Reads only: it never starts a job and changes
        nothing. The "Save as PDF" target of the print dialog is not a printer —
        use app_print_to_pdf for that.

        MCP tool ``app_list_printers`` (read-only).
        """
        return self._call_tool("app_list_printers", _pack({}))

    def list_layers(self) -> Any:
        """List markup layers.

        List the markup layers of the active document in panel order: id, name,
        colour, visible, printable, locked, the number of markups on it, whether
        it is the current layer (where new markups land) and whether it is the
        default layer. Markups without a layer of their own are on the default
        layer. Reads only.

        MCP tool ``app_list_layers`` (read-only).
        """
        return self._call_tool("app_list_layers", _pack({}))

    def create_layer(self, name: str, *, color: Optional[str] = None, current: Optional[bool] = None, locked: Optional[bool] = None, printable: Optional[bool] = None, visible: Optional[bool] = None) -> Any:
        """Create markup layer.

        Create a markup layer in the active document, at the end of the layer
        list. Names are unique (case-insensitive). Returns the new layer. The
        layers are saved with the document as optional content groups, so other
        PDF readers can switch them too.

        Args:
            name (string, required): Name of the new layer.
            color (string): Layer colour as #rrggbb.
            current (boolean): Make it the current layer, so new markups land on
                it.
            locked (boolean): Visible, but its markups cannot be selected or
                moved (default false).
            printable (boolean): Printed and exported (default true).
            visible (boolean): Shown on screen (default true). A hidden layer is
                also not printed, not exported and not selectable.

        MCP tool ``app_create_layer`` (changes state).
        """
        return self._call_tool("app_create_layer", _pack({"color": color, "current": current, "locked": locked, "name": name, "printable": printable, "visible": visible}))

    def set_layer(self, layer: str, *, color: Optional[str] = None, current: Optional[bool] = None, locked: Optional[bool] = None, name: Optional[str] = None, printable: Optional[bool] = None, visible: Optional[bool] = None) -> Any:
        """Change markup layer.

        Change a markup layer of the active document: switch it on or off, make
        it printable or not, lock or unlock it, rename it, set its colour, or
        make it the current layer. A layer that is switched off is not drawn,
        not selectable, not printed and not exported; its markups come back
        unchanged when it is switched on. Returns the layer and what changed.

        Args:
            layer (string, required): The layer, by id or name (see
                app_list_layers).
            color (string): Layer colour as #rrggbb.
            current (boolean): true makes it the current layer.
            locked (boolean): Lock the layer: visible, but not selectable or
                movable.
            name (string): New name. The default layer cannot be renamed.
            printable (boolean): Print and export the layer.
            visible (boolean): Switch the layer on (true) or off (false).

        MCP tool ``app_set_layer`` (modifies or discards state).
        """
        return self._call_tool("app_set_layer", _pack({"color": color, "current": current, "layer": layer, "locked": locked, "name": name, "printable": printable, "visible": visible}))

    def snippet_flatten(self, id: str, *, flattened: Optional[bool] = None) -> Any:
        """Flatten vector snippet.

        Mark a pasted vector snippet as flattened: it stays visible but is no
        longer selectable, and on the next save it is drawn into the page
        content instead of being stored as an annotation.

        Args:
            id (string, required): Annotation id of the vectorSnippet.
            flattened (boolean): false un-flattens it again (default true).

        MCP tool ``app_snippet_flatten`` (modifies or discards state).
        """
        return self._call_tool("app_snippet_flatten", _pack({"flattened": flattened, "id": id}))

    def symbol_scale(self, *, scale: Optional[float] = None) -> Any:
        """Symbol placement scale.

        Get or set the placement scale for symbols from the symbol palette (1 =
        real size, 2 = twice as large). Applies to symbols placed from now on;
        symbols already on the drawing are unchanged. Range 0.1 to 10. Without
        `scale` it returns the current value.

        Args:
            scale (number): New placement scale.

        MCP tool ``app_symbol_scale`` (changes state).
        """
        return self._call_tool("app_symbol_scale", _pack({"scale": scale}))

    def titleblock(self, *, fields: Optional[Dict[str, Any]] = None, page: Optional[float] = None) -> Any:
        """Fill title block.

        Read or fill the title block fields by NAME (projectnaam, adres,
        opdrachtgever, status, projectnr, fase, auteur, schaal, datum_eerste,
        wijziging, documenttype, kenmerk — whatever the title block defines).
        Without `fields` it lists the fields and their current values; with
        `fields` it fills them, e.g. {"projectnaam": "Woonhuis", "schaal":
        "1:50"}. Unknown names are reported, not silently ignored.

        Args:
            fields (object): Field name to new value.
            page (number): Limit to one page (default: all pages).

        MCP tool ``app_titleblock`` (modifies or discards state).
        """
        return self._call_tool("app_titleblock", _pack({"fields": fields, "page": page}))

    def floorplan(self, action: Literal["inspect", "wall", "rooms", "dimensions"], *, add_points: Optional[List[Any]] = None, chain_of: Optional[str] = None, end: Optional[Dict[str, Any]] = None, inside_side: Optional[Literal["left", "right"]] = None, insulation: Optional[str] = None, join_end: Optional[bool] = None, join_start: Optional[bool] = None, layers: Optional[List[Any]] = None, material: Optional[str] = None, max_opening_mm: Optional[float] = None, min_pier_mm: Optional[float] = None, names: Optional[List[Any]] = None, offset_mm: Optional[float] = None, openings: Optional[List[Any]] = None, page: Optional[float] = None, place: Optional[bool] = None, refresh: Optional[bool] = None, remove_points: Optional[List[Any]] = None, seeds: Optional[List[Any]] = None, show_unit: Optional[bool] = None, side: Optional[Literal["left", "right"]] = None, start: Optional[Dict[str, Any]] = None, thickness_mm: Optional[float] = None, tolerance: Optional[float] = None, total_offset_mm: Optional[float] = None, wall_id: Optional[str] = None, wall_ids: Optional[List[Any]] = None) -> Any:
        """Draw floor plan.

        Draw a building floor plan with the parts related to each other, instead
        of loose shapes stacked on top of one another. Four actions. "wall"
        draws ONE wall run with its openings: the wall is split at every door
        and window, so the opening really interrupts the wall (the hatch stops
        at the reveal) and the frame symbol sits in the gap at the wall's own
        thickness and angle; it returns the wall segment ids in order. Doors and
        windows are drawn as real frames: timber stiles (67 x 114 mm by default)
        with a rebate, double glazing or a 40 mm door leaf with its swing. With
        layers the run is a layered (cavity) wall: start/end are its outside
        face, every drawn layer gets its own wall segments cut to its own
        opening (the outer leaf overlaps the frame, the insulation closes
        against it, the inner leaf keeps a reveal with clearance), the frame
        stands in the cavity behind the outer leaf, and runs whose outside faces
        meet in a corner are mitred layer by layer. "rooms" derives the enclosed
        rooms from the walls on a page - net area (inside the wall faces),
        perimeter and a label point that always falls inside the room - and
        reports wall ends that leave the contour open instead of silently
        filling half an area; a door opening does not break the enclosure. With
        place:true it puts each room on the sheet as a quiet room area (thin
        grey outline, no hatch or fill, drawn behind the walls and frames) plus
        ONE movable room tag, remembering the seed point. The room itself
        carries the name and the optional number (kept on save and reopen); the
        tag shows the room's name, number and net area. Placing a room that is
        already on the sheet adds no second area, only a tag if it has none. A
        click never selects a room (walls, frames and dimensions always win);
        reach it through its tag. names:[{id or x,y, name, number}] sets name
        and number on placed rooms; rooms and inspect report id, name, number
        and tagIds of placed rooms. With refresh:true it re-derives them from
        the walls as they are now, so a room that grew because a wall moved
        updates its area and its tag, and the tag keeps its place relative to
        the room. "dimensions" places a dimension chain along a wall run (pier,
        opening, pier, ...) plus an overall dimension, measured the way a
        draughtsman does: every point is ANCHORED to the wall face on the side
        of the chain (for a facade built from separate layers, the face of the
        outermost layer), and the end points sit on the outer corner of the
        building, also where the own segment stops short at a butt joint. The
        dimensions show the number only, black and thin, with extension lines
        that start a small gap from the wall face and run just past the
        dimension line, and the dimension line runs a little past the outer
        extension lines (sizes in paper millimetres, so they do not change with
        the drawing scale); the default distances grow with the drawing scale so
        text never runs into the lines. With refresh:true every anchored
        dimension on the page is recomputed the same way, and a dimension whose
        wall disappeared is reported as detached rather than broken. With
        chainOf (the id of any dimension) plus addPoints and/or removePoints an
        existing dimension or chain is extended or shortened in place: a point
        between two extension lines splits that segment, a point outside makes
        the chain longer, removing a point merges two segments; the overall
        dimension follows, the new segments copy the style of their neighbour,
        and a point on a wall face is anchored to that wall. A single dimension
        extended this way becomes a chain. "inspect" reads back what is on the
        page: walls with their length and thickness, openings with width, sill
        and height, the rooms it finds, open contour ends and how many anchored
        dimensions there are. Coordinates are page points at 100% zoom; sizes
        are real millimetres, so the page needs a measurement scale
        (app_set_measure_scale) first. Everything one call creates or changes
        goes into a single undo step.

        Args:
            action (one of "inspect", "wall", "rooms", "dimensions", required):
                What to do.
            add_points (array) [MCP: addPoints]: dimensions with chainOf: points
                {x, y} in page points to add as extension lines, between or outside
                the existing ones.
            chain_of (string) [MCP: chainOf]: dimensions: the id of a dimension
                (measureDistance) whose chain you want to extend or shorten, with
                addPoints and/or removePoints.
            end (object): wall: end of the run as {x, y} in page points.
            inside_side (one of "left", "right") [MCP: insideSide]: wall with
                layers: which side of start->end is inside (default right; a
                clockwise outline has the inside on the right).
            insulation (string): wall: insulation sub-material when material is
                isolatie (steenwol, glaswol, pir, eps, kooltherm, pur).
            join_end (boolean) [MCP: joinEnd]: wall: false = the end of the run
                never joins another wall (see joinStart; default true).
            join_start (boolean) [MCP: joinStart]: wall: false = the start of
                the run never joins another wall: no mitre, no T, no trim; the end
                keeps a plain butt cap exactly where it is drawn (default true).
                Otherwise walls that touch are joined automatically: coincident end
                points are mitred; ends that just pass or fall short of a wall of
                the same material are trimmed to a closed corner; an end that stops
                on a continuing wall (on its centre line, on its face, just short of
                it or inside it) forms a T, where the same material flows into it
                and another material butts against its face with a seam. Later:
                app_update_annotation props noJoinStart / noJoinEnd.
            layers (array): wall: build-up of a layered (cavity) wall, from
                outside to inside, each {thicknessMm, material, insulation};
                material none is an air cavity (not drawn). The run's start/end are
                then the outside face, thicknessMm and material of the run are
                ignored. Answer: layers[i].wallIds per drawn layer, per opening
                frame and layerOpeningsMm, corners = layers mitred at start/end.
            material (string): wall: hatch material id, e.g.
                nen47-metselwerk-baksteen, nen47-metselwerk-kunststeen,
                nen47-beton-gewapend, isolatie, none.
            max_opening_mm (number) [MCP: maxOpeningMm]: rooms/inspect: widest
                gap between two aligned wall ends that still counts as an opening
                rather than a hole in the contour (default 3000).
            min_pier_mm (number) [MCP: minPierMm]: wall: smallest piece of wall
                that must remain beside an opening (default 0).
            names (array): rooms: set the name and/or number of placed rooms,
                each {id (the room area) or x, y (a point inside), name, number}.
            offset_mm (number) [MCP: offsetMm]: dimensions: distance from the
                wall face to the chain, in mm (default 500 at 1:50; larger at
                smaller scales, so the text fits).
            openings (array): wall: the doors and windows in this run. Each:
                kind (door|window), widthMm (frame size, outside dimensions; in a
                single wall this is also the opening), alongMm (centre, measured
                from start along the wall), sillMm, heightMm, swing (left|right: the
                hinge side seen from the side the door opens away from), openSide
                (left|right of the wall direction) or openTo ({x, y}: a point in the
                room the door opens into; for a window its inside), windowType
                (fixed|turn|pivot|tilt), showSwing (window: true also draws the
                opening direction of a turn sash as a dashed quarter circle; default
                false, because in a plan it reads as a door). Frame, all optional:
                stileWidthMm (default 67), frameDepthMm (default 114, never deeper
                than the wall), framePositionMm (outside face of the wall to outside
                face of the frame; default: behind the outer leaf in a layered wall,
                centred in a single wall), overlapMm (outer leaf over the frame;
                default 20 in a layered wall), clearanceMm (reveal of the inner
                leaf; default 10 in a layered wall), leafThicknessMm (door leaf,
                default 40).
            page (number): 1-based page (default: the current page).
            place (boolean): rooms: also put the rooms on the sheet instead of
                only reporting them.
            refresh (boolean): rooms/dimensions: recompute what is already on
                the sheet from the walls as they are now.
            remove_points (array) [MCP: removePoints]: dimensions with chainOf:
                points {x, y} near the extension lines to remove (the measured point
                or anywhere along the extension line).
            seeds (array): rooms: points inside the rooms you want, each {x, y,
                name, number}; number is optional. Without seeds every room found is
                reported.
            show_unit (boolean) [MCP: showUnit]: dimensions: also show the unit
                behind the number (default false: the number only, as on a building
                drawing).
            side (one of "left", "right"): dimensions: which side of the run the
                chain goes, seen along its direction (default right). For an outline
                drawn clockwise on the sheet, left is outside.
            start (object): wall: start of the run as {x, y} in page points (the
                wall centre line; with layers the outside face of the wall).
            thickness_mm (number) [MCP: thicknessMm]: wall: real wall thickness
                in mm (default 100).
            tolerance (number): dimensions with removePoints: how close (page
                points) a point must be to an extension line (default 6).
            total_offset_mm (number) [MCP: totalOffsetMm]: dimensions: distance
                from the wall face to the overall dimension, in mm (default offsetMm
                plus one line of text, at least 350).
            wall_id (string) [MCP: wallId]: dimensions: a single wall annotation
                to dimension.
            wall_ids (array) [MCP: wallIds]: dimensions: the wall segments of
                one run, in order along the run (as returned by action "wall").

        MCP tool ``app_floorplan`` (modifies or discards state).
        """
        return self._call_tool("app_floorplan", _pack({"action": action, "addPoints": add_points, "chainOf": chain_of, "end": end, "insideSide": inside_side, "insulation": insulation, "joinEnd": join_end, "joinStart": join_start, "layers": layers, "material": material, "maxOpeningMm": max_opening_mm, "minPierMm": min_pier_mm, "names": names, "offsetMm": offset_mm, "openings": openings, "page": page, "place": place, "refresh": refresh, "removePoints": remove_points, "seeds": seeds, "showUnit": show_unit, "side": side, "start": start, "thicknessMm": thickness_mm, "tolerance": tolerance, "totalOffsetMm": total_offset_mm, "wallId": wall_id, "wallIds": wall_ids}))

    def facade_element(self, action: Literal["create", "get", "addMullion", "removeMullion", "moveMullion", "setMullionType", "setPanel", "divide"], *, along_mm: Optional[float] = None, at_mm: Optional[float] = None, by_mm: Optional[float] = None, end: Optional[Dict[str, Any]] = None, field: Optional[float] = None, field_indexes: Optional[List[float]] = None, field_widths_mm: Optional[List[float]] = None, fields: Optional[float] = None, frame_type: Optional[str] = None, from_mm: Optional[float] = None, id: Optional[str] = None, inside_side: Optional[Literal["right", "left"]] = None, length_mm: Optional[float] = None, mullion: Optional[float] = None, mullion_type: Optional[str] = None, offset_mm: Optional[float] = None, page: Optional[float] = None, panel: Optional[Union[str, Dict[str, Any]]] = None, panels: Optional[List[Any]] = None, preset: Optional[Literal["curtainWall", "windowFrame"]] = None, start: Optional[Dict[str, Any]] = None, to_mm: Optional[float] = None, wall_id: Optional[str] = None) -> Any:
        """Draw facade element.

        Draw and edit a facade element in a floor plan: a curtain wall or a
        window frame, as ONE object along a line with an outer frame, mullions
        on the field boundaries and a panel in every field. Everything is at
        real size (mm) from the measurement scale, so set one first with
        app_set_measure_scale. Actions: "create" places a new element, either
        loose along start/end (page points), or IN an existing wall (wallId plus
        fromMm or alongMm and lengthMm): the wall is then cut over the length of
        the element, like a door or window opening, and the element sits in the
        gap; offsetMm moves it across the wall build-up (+ = right of the wall
        direction). The division is fields (number of equal fields,
        centre-to-centre) or fieldWidthsMm (centre-to-centre widths that add up
        to the length); without either it divides itself into fields of about
        1200 mm (curtain wall) or 900 mm (window frame). "get" returns one
        element (id) with its mullions and fields, or without id a summary of
        every element on the page. Edits (all need id): "addMullion" splits a
        field at atMm (from the start) or in the middle of field;
        "removeMullion" merges the two fields beside mullion (index) or the
        mullion nearest atMm; "moveMullion" moves it to toMm or by byMm;
        "setMullionType" swaps the type of mullion (index 0 and the last index
        are the outer frame; without mullion or atMm all intermediate mullions);
        "setPanel" swaps the panel of field, fieldIndexes or the field at atMm;
        "divide" divides again into fields or fieldWidthsMm. Mullions are
        numbered from 0 (frame at the start) to n (frame at the end); field i
        lies between mullion i and i+1. Fields never become narrower than 100 mm
        clear and the overall length stays the same, except for divide with
        fieldWidthsMm. Mullion types: curtain wall alu-50x150 (default),
        alu-50x200, alu-65x250; window frame hout-67x114 (default), hout-67x139,
        hout-90x114 (width x depth in mm). Panels: curtain wall glass, solid,
        door, open; window frame glass, turnSash, door, solid. A panel is a name
        or {type, hinge: start|end, swing: inside|outside} for a door or turn
        sash. Every call is a single undo step and returns the element as it is
        now.

        Args:
            action (one of "create", "get", "addMullion", "removeMullion",
                "moveMullion", "setMullionType", "setPanel", "divide", required):
                What to do.
            along_mm (number) [MCP: alongMm]: create in a wall: distance from
                the wall start to the MIDDLE of the element, in mm (alternative to
                fromMm; without both the element is centred).
            at_mm (number) [MCP: atMm]: Position along the element from its
                start, in mm: where addMullion splits, which mullion (nearest) or
                field setPanel/removeMullion/moveMullion/setMullionType means.
            by_mm (number) [MCP: byMm]: moveMullion: shift in mm (+ = towards
                the end).
            end (object): create (loose): end of the element as {x, y} in page
                points.
            field (number): addMullion: split this field in the middle;
                setPanel: the field index (0 = at the start).
            field_indexes (array) [MCP: fieldIndexes]: setPanel: several field
                indexes at once.
            field_widths_mm (array) [MCP: fieldWidthsMm]: create/divide:
                centre-to-centre field widths in mm, from the start.
            fields (number): create/divide: number of equal fields.
            frame_type (string) [MCP: frameType]: create: type of the outer
                frame (both ends).
            from_mm (number) [MCP: fromMm]: create in a wall: distance from the
                wall start to the START of the element, in mm.
            id (string): The facade element to read or edit (as returned by
                create or get).
            inside_side (one of "right", "left") [MCP: insideSide]: create:
                which side of the drawing direction is inside (doors swing inside by
                default; default right).
            length_mm (number) [MCP: lengthMm]: create in a wall: length of the
                element = width of the gap, in mm (or give fieldWidthsMm).
            mullion (number): removeMullion/moveMullion/setMullionType: mullion
                index (0 = frame at the start).
            mullion_type (string) [MCP: mullionType]:
                create/addMullion/setMullionType: mullion type id, e.g. alu-50x150
                or hout-67x114.
            offset_mm (number) [MCP: offsetMm]: create in a wall: position
                across the wall build-up, mm from the wall centre line, + = right of
                the wall direction (default 0).
            page (number): 1-based page (default: the current page).
            panel (string or object): create: panel for every field not given in
                panels; setPanel: the new panel. A name (glass, solid, door, open,
                turnSash) or {type, hinge: start|end, swing: inside|outside}; an
                object without type only changes hinge/swing.
            panels (array): create: the panel of each field, from the start (a
                name or {type, hinge, swing}).
            preset (one of "curtainWall", "windowFrame"): create: which kind of
                element (default curtainWall).
            start (object): create (loose): start of the element as {x, y} in
                page points.
            to_mm (number) [MCP: toMm]: moveMullion: new position from the
                start, in mm.
            wall_id (string) [MCP: wallId]: create: put the element in this wall
                annotation; the wall is cut over the element's length.

        MCP tool ``app_facade_element`` (modifies or discards state).
        """
        return self._call_tool("app_facade_element", _pack({"action": action, "alongMm": along_mm, "atMm": at_mm, "byMm": by_mm, "end": end, "field": field, "fieldIndexes": field_indexes, "fieldWidthsMm": field_widths_mm, "fields": fields, "frameType": frame_type, "fromMm": from_mm, "id": id, "insideSide": inside_side, "lengthMm": length_mm, "mullion": mullion, "mullionType": mullion_type, "offsetMm": offset_mm, "page": page, "panel": panel, "panels": panels, "preset": preset, "start": start, "toMm": to_mm, "wallId": wall_id}))

    def list_system_types(self, *, id: Optional[str] = None) -> Any:
        """List system types.

        List the reusable system types (suspended ceilings, floor slabs, panel
        systems) of the app library, or one type by id. Each entry has its
        stable id, owner, revision, whether the user edited it, the validated
        definition, unconfirmed dimensions and stored values that fail
        validation. Compare libraryRevision between calls to detect changes.
        Reads only.

        Args:
            id (string): Stable id of one system type.

        MCP tool ``app_list_system_types`` (read-only).
        """
        return self._call_tool("app_list_system_types", _pack({"id": id}))

    def register_system_type(self, key: str, definition: Dict[str, Any], *, restore: Optional[bool] = None, schema: Optional[Literal[1]] = None) -> Any:
        """Register system type.

        Register a system type owned by MCP under the id mcp:<key>. Repeating
        the call with the same definition changes nothing (status unchanged),
        and a definition the user edited in the app is kept (status
        kept-user-edit) and never overwritten. A different definition replaces
        an existing mcp:<key> type that the user has not edited (status updated)
        and redraws every system that uses it. Unknown fields, out-of-range
        values and layered definitions are rejected. Missing dimensions stay
        unconfirmed.

        Args:
            key (string, required): Stable key: lowercase letters, digits, dot,
                underscore or hyphen (1-64).
            definition (object, required)
            restore (boolean): Recreate a type the user removed. Only on an
                explicit user request.
            schema (one of 1)

        MCP tool ``app_register_system_type`` (modifies or discards state).
        """
        return self._call_tool("app_register_system_type", _pack({"definition": definition, "key": key, "restore": restore, "schema": schema}))

    def update_system_type(self, id: str, expected_revision: int, changes: Dict[str, Any], *, schema: Optional[Literal[1]] = None) -> Any:
        """Update system type.

        Update a system type owned by MCP (id mcp:<key>). Pass the revision you
        last read as expectedRevision; a stale revision is rejected with the
        current revision. Types of the app or of extensions cannot be changed
        here. Nested values (sparingRegels, paneelTypen) are replaced as a
        whole; null clears an optional field.

        Args:
            id (string, required)
            expected_revision (integer, required; min 1) [MCP: expectedRevision]
            changes (object, required)
            schema (one of 1)

        MCP tool ``app_update_system_type`` (modifies or discards state).
        """
        return self._call_tool("app_update_system_type", _pack({"changes": changes, "expectedRevision": expected_revision, "id": id, "schema": schema}))

    def open_system_type_editor(self, id: str) -> Any:
        """Open system type editor.

        Open the app's system type editor with the given type selected, or
        select it in the editor that is already open without discarding
        unapplied edits. Returns immediately; the user applies or cancels in the
        app. Does not change any data.

        Args:
            id (string, required): Stable id of the system type to select.

        MCP tool ``app_open_system_type_editor`` (read-only).
        """
        return self._call_tool("app_open_system_type_editor", _pack({"id": id}))

    def get_system_geometry(self, annotation_id: str, *, expected_document_revision: Optional[str] = None, expected_type_revision: Optional[int] = None, schema: Optional[Literal[1]] = None) -> Any:
        """Get system geometry.

        Get the geometry of one system (suspended ceiling, floor slab, panel
        field) in the active document, computed by the app's own geometry
        engine: panels with clipped outlines, grid lines, openings, trimmers,
        edge segments and component positions, in millimetres in the system's
        own frame (independent of zoom and view rotation; placement maps it onto
        the page). Includes the document and type revisions and whether every
        physical dimension is confirmed. Pass expectedDocumentRevision and
        expectedTypeRevision to reject a stale snapshot. Reads only.

        Args:
            annotation_id (string, required) [MCP: annotationId]: Id of the
                system annotation (type systeemraster) in the active document.
            expected_document_revision (string) [MCP: expectedDocumentRevision]:
                document.revision of an earlier snapshot; a different current
                revision is rejected.
            expected_type_revision (integer; min 1) [MCP: expectedTypeRevision]:
                type.revision of an earlier snapshot; a different current revision
                is rejected.
            schema (one of 1)

        MCP tool ``app_get_system_geometry`` (read-only).
        """
        return self._call_tool("app_get_system_geometry", _pack({"annotationId": annotation_id, "expectedDocumentRevision": expected_document_revision, "expectedTypeRevision": expected_type_revision, "schema": schema}))

    def call_extension_command(self, tool: str, *, arguments: Optional[Dict[str, Any]] = None) -> Any:
        """Run extension command.

        Run a structured command of a loaded extension. Every such command is
        also listed as its own tool named ext_<extension>__<command>; use this
        tool when that tool is not in your list, for example after installing or
        reloading an extension. app_list_extensions with includeContributions
        lists each command with its input and output schema. The arguments are
        checked against the input schema before the extension runs; a mutating
        command also needs idempotencyKey and revisionContext. Returns ok,
        requestId, extension, command and result, or ok: false with an error
        code such as UNKNOWN_COMMAND, INVALID_ARGUMENT, STALE_REVISION,
        IDEMPOTENCY_KEY_REUSED, COMMAND_TIMEOUT or EXTENSION_UNLOADED.

        Args:
            tool (string, required): Tool name of the extension command,
                ext_<extension>__<command>.
            arguments (object): Arguments for the command, as described by its
                input schema.

        MCP tool ``app_call_extension_command`` (modifies or discards state).
        """
        return self._call_tool("app_call_extension_command", _pack({"arguments": arguments, "tool": tool}))

    def list_extensions(self, *, include_contributions: Optional[bool] = None) -> Any:
        """List extensions.

        List the app's extensions: every installed and every loaded extension
        with its id, name, version, installed version, whether it is loaded and
        activated, its status (active, failed, notLoaded, busy), the code and
        message of the last failure, who made the last change (ui, mcp or
        startup) and whether it uses an old-style id. Broken folders in the
        extensions directory are listed under problems instead of being skipped.
        Reads only.

        Args:
            include_contributions (boolean) [MCP: includeContributions]: Also
                list each extension's registered contributions (ribbon tabs, command
                count, annotation types, palettes, property panels, and structured
                commands with their input and output schemas). Default false.

        MCP tool ``app_list_extensions`` (read-only).
        """
        return self._call_tool("app_list_extensions", _pack({"includeContributions": include_contributions}))

    def install_extension(self, path: str, replace: Literal["never", "ifNewer", "always"], idempotency_key: str) -> Any:
        """Install extension.

        Install or update an extension from a local .oppx package, without a
        file dialog and without restarting the app: the package is checked and
        unpacked by the app, then the new version is activated. If the new
        version fails to load or activate, the previous working version is
        restored and stays active (rolledBack: true). Open PDF tabs and unsaved
        changes are not touched. Returns ok, outcome (installed, updated,
        unchanged), id, version, previousVersion, activated and the registered
        contributions, or ok: false with an error code such as PATH_NOT_ALLOWED,
        PACKAGE_INVALID, MANIFEST_INVALID, ALREADY_INSTALLED, VERSION_NOT_NEWER,
        MODULE_LOAD_FAILED or ACTIVATION_FAILED.

        Args:
            path (string, required): Absolute path to a local .oppx package.
                Relative paths, network shares and URLs are refused.
            replace (one of "never", "ifNewer", "always", required): What to do
                when the extension id is already installed: 'never' refuses,
                'ifNewer' replaces only a lower version, 'always' replaces (also a
                downgrade). An identical package (same SHA-256) is always reported
                as 'unchanged'.
            idempotency_key (string, required) [MCP: idempotencyKey]:
                Caller-chosen key for this install request. Repeating a call with
                the same key, path and replace returns the stored result without
                installing again; the same key with a different path or replace is
                refused.

        MCP tool ``app_install_extension`` (modifies or discards state).
        """
        return self._call_tool("app_install_extension", _pack({"idempotencyKey": idempotency_key, "path": path, "replace": replace}))

    def reload_extension(self, id: str) -> Any:
        """Reload extension.

        Reload an installed extension from disk: deactivate it, remove
        everything it registered (ribbon tabs, commands, annotation types,
        palettes, panels) and activate it again, without restarting the app. If
        the reloaded code fails, the previous code is activated again
        (rolledBack: true). Returns ok, outcome 'reloaded', id, version,
        activated and contributions, or ok: false with an error code such as
        NOT_INSTALLED, MODULE_LOAD_FAILED or ACTIVATION_FAILED.

        Args:
            id (string, required): Extension id from app_list_extensions.

        MCP tool ``app_reload_extension`` (changes state).
        """
        return self._call_tool("app_reload_extension", _pack({"id": id}))
